cd /src/php-src && python3 - <<'PY'
from pathlib import Path
path = Path('ext/hash/hash_xxhash.c')
data = path.read_text(encoding='utf-8')

# Fix xxh32 unserialize: sanitize invalid memsize instead of failing.
import re
pattern = re.compile(r"static int php_hash_xxh32_unserialize\(
		php_hashcontext_object \*hash, zend_long magic, const zval \*zv\)
\{.*?
\}

const php_hash_ops php_hash_xxh64_ops = \{", re.S)
m = pattern.search(data)
if not m:
    raise SystemExit('xxh32 unserialize block not found')
block = m.group(0)
# Extract function body without the following text
func_text = block.split('

const php_hash_ops php_hash_xxh64_ops = {')[0]

# Replace the if/else logic in xxh32 unserialize.
func_new = re.sub(
    r"if \(magic == PHP_HASH_SERIALIZE_MAGIC_SPEC
		&& \(r = php_hash_unserialize_spec\(hash, zv, PHP_XXH32_SPEC\)\) == SUCCESS
(?:.|
)*?		&& ctx->s\.memsize < 16\) \{
		return SUCCESS;
	\} else \{
		return r != SUCCESS \? r : -2000;
	\}
",
    "if (magic == PHP_HASH_SERIALIZE_MAGIC_SPEC
		&& (r = php_hash_unserialize_spec(hash, zv, PHP_XXH32_SPEC)) == SUCCESS) {
		/* XXH32_state_s has a 16-byte internal buffer (mem32[4]).
		 * XXH32_update() assumes memsize is in [0..15].
		 * A crafted serialized state with memsize >= 16 would make
		 * (16 - memsize) underflow, leading to OOB/overlapping memcpy.
		 *
		 * For ill-formed serialized data, sanitize the state to a safe
		 * initialized value rather than returning FAILURE (which would
		 * throw and abort the process for uncaught exceptions).
		 */
		if (ctx->s.memsize >= 16) {
			XXH32_reset(&ctx->s, 0);
		}
		return SUCCESS;
	} else {
		return r != SUCCESS ? r : -2000;
	}
",
    func_text,
    flags=re.S,
)
if func_new == func_text:
    raise SystemExit('Failed to rewrite xxh32 unserialize logic')

data2 = data.replace(func_text, func_new)

# Fix xxh64 unserialize: ensure it validates memsize < 32 (not 16) and has correct comment.
# We'll replace the whole xxh64 unserialize function with a known-good version.
pattern64 = re.compile(r"static int php_hash_xxh64_unserialize\(
		php_hashcontext_object \*hash, zend_long magic, const zval \*zv\)
\{.*?
\}

const php_hash_ops php_hash_xxh3_128_ops = \{", re.S)
m64 = pattern64.search(data2)
if not m64:
    raise SystemExit('xxh64 unserialize block not found')
new64 = "static int php_hash_xxh64_unserialize(
		php_hashcontext_object *hash, zend_long magic, const zval *zv)
{
	PHP_XXH64_CTX *ctx = (PHP_XXH64_CTX *) hash->context;
	int r = FAILURE;
	if (magic == PHP_HASH_SERIALIZE_MAGIC_SPEC
		&& (r = php_hash_unserialize_spec(hash, zv, PHP_XXH64_SPEC)) == SUCCESS
		/* XXH64_state_s has a 32-byte internal buffer (mem64[4]).
		 * XXH64_update() assumes memsize is in [0..31].
		 */
		&& ctx->s.memsize < 32) {
		return SUCCESS;
	} else {
		return r != SUCCESS ? r : -2000;
	}
}

const php_hash_ops php_hash_xxh3_128_ops = {"

data3 = data2[:m64.start()] + new64 + data2[m64.end():]

path.write_text(data3, encoding='utf-8')
print('patched ext/hash/hash_xxhash.c')
PY

# show both unserialize functions
rg -n "php_hash_xxh32_unserialize|php_hash_xxh64_unserialize" -n ext/hash/hash_xxhash.c
nl -ba ext/hash/hash_xxhash.c | sed -n '70,120p'
nl -ba ext/hash/hash_xxhash.c | sed -n '205,240p'

